import {
  access,
  mkdir,
  mkdtemp,
  readFile,
  rename,
  rm,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { appPaths, type Config } from "./config.ts";

const marker =
  "# Generated by rprr; edit config and rerun `rprr service install`.";

export function servicePaths() {
  const directory = join(
    dirname(dirname(appPaths().config)),
    "systemd",
    "user",
  );
  return {
    directory,
    service: join(directory, "rprr.service"),
    timer: join(directory, "rprr.timer"),
  };
}

function quoted(value: string): string {
  if (/[\r\n]/.test(value)) throw new Error("Invalid newline in service path");
  return JSON.stringify(value.replaceAll("%", "%%"));
}

export function renderUnits(bun: string, agent: string, gh: string) {
  const executable = fileURLToPath(new URL("../bin/rprr.ts", import.meta.url));
  const path = [
    ...new Set([
      dirname(bun),
      dirname(agent),
      dirname(gh),
      "/usr/local/bin",
      "/usr/bin",
      "/bin",
    ]),
  ].join(":");
  const environment = [
    `Environment=${quoted(`PATH=${path}`)}`,
    ...["XDG_CONFIG_HOME", "XDG_STATE_HOME", "XDG_CACHE_HOME", "GH_CONFIG_DIR"]
      .filter((name) => process.env[name])
      .map((name) => `Environment=${quoted(`${name}=${process.env[name]}`)}`),
  ];
  return {
    service: `${marker}\n[Unit]\nDescription=Review directly requested GitHub pull requests with RPRR\n\n[Service]\nType=oneshot\n${environment.join("\n")}\nExecStart=${quoted(bun)} ${quoted(executable)} poll\n`,
    timer: `${marker}\n[Unit]\nDescription=Check for RPRR review requests every 15 minutes\n\n[Timer]\nOnCalendar=*:0/15\nPersistent=true\n\n[Install]\nWantedBy=timers.target\n`,
  };
}

async function command(
  command: string,
  args: string[],
  allowFailure = false,
): Promise<string> {
  const child = Bun.spawn([command, ...args], {
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(child.stdout).text(),
    new Response(child.stderr).text(),
    child.exited,
  ]);
  if (exitCode !== 0 && !allowFailure)
    throw new Error(
      `${command} ${args.join(" ")} failed: ${stderr.trim() || stdout.trim()}`,
    );
  return stdout.trim();
}

async function existing(path: string): Promise<string | undefined> {
  try {
    return await readFile(path, "utf8");
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT")
      return undefined;
    throw error;
  }
}

async function writeUnit(path: string, content: string): Promise<void> {
  const current = await existing(path);
  if (current === content) return;
  if (current && !current.startsWith(marker))
    throw new Error(
      `Refusing to overwrite a unit not generated by rprr: ${path}`,
    );
  const temporary = `${path}.${crypto.randomUUID()}.tmp`;
  try {
    await writeFile(temporary, content, { flag: "wx", mode: 0o644 });
    await rename(temporary, path);
  } finally {
    await rm(temporary, { force: true });
  }
}

export async function installService(
  config: Config,
): Promise<ReturnType<typeof servicePaths>> {
  if (process.platform !== "linux")
    throw new Error("User timer setup requires Linux");
  const bun = Bun.which("bun");
  const agent = Bun.which(config.agent.command);
  const gh = Bun.which("gh");
  if (
    !bun ||
    !agent ||
    !gh ||
    !Bun.which("systemctl") ||
    !Bun.which("systemd-analyze")
  )
    throw new Error(
      "Service setup requires bun, gh, the configured agent, systemctl, and systemd-analyze",
    );
  const units = renderUnits(bun, agent, gh);
  const staging = await mkdtemp(join(tmpdir(), "rprr-units-"));
  try {
    const stagedService = join(staging, "rprr.service");
    const stagedTimer = join(staging, "rprr.timer");
    await Promise.all([
      writeFile(stagedService, units.service),
      writeFile(stagedTimer, units.timer),
    ]);
    await command("systemd-analyze", [
      "--user",
      "verify",
      stagedService,
      stagedTimer,
    ]);
  } finally {
    await rm(staging, { recursive: true, force: true });
  }
  const paths = servicePaths();
  for (const path of [paths.service, paths.timer]) {
    const current = await existing(path);
    if (current && !current.startsWith(marker))
      throw new Error(
        `Refusing to overwrite a unit not generated by rprr: ${path}`,
      );
  }
  await mkdir(paths.directory, { recursive: true, mode: 0o700 });
  await writeUnit(paths.service, units.service);
  await writeUnit(paths.timer, units.timer);
  await command("systemctl", ["--user", "daemon-reload"]);
  return paths;
}

export async function enableService(): Promise<void> {
  await access(servicePaths().timer);
  await command("systemctl", ["--user", "enable", "--now", "rprr.timer"]);
}

export async function disableService(): Promise<void> {
  await command("systemctl", ["--user", "disable", "--now", "rprr.timer"]);
}

export async function uninstallService(): Promise<void> {
  const paths = servicePaths();
  const installed = await Promise.all([
    existing(paths.service),
    existing(paths.timer),
  ]);
  if (installed.every((content) => content === undefined)) return;
  for (const [index, path] of [paths.service, paths.timer].entries()) {
    const content = installed[index];
    if (content && !content.startsWith(marker))
      throw new Error(
        `Refusing to remove a unit not generated by rprr: ${path}`,
      );
  }
  await command(
    "systemctl",
    ["--user", "disable", "--now", "rprr.timer"],
    true,
  );
  await Promise.all([
    rm(paths.service, { force: true }),
    rm(paths.timer, { force: true }),
  ]);
  await command("systemctl", ["--user", "daemon-reload"]);
}

export async function serviceStatus() {
  const paths = servicePaths();
  const installed =
    (await existing(paths.service)) !== undefined &&
    (await existing(paths.timer)) !== undefined;
  if (!Bun.which("systemctl"))
    return {
      installed,
      enabled: "unavailable",
      active: "unavailable",
      lastResult: "",
      nextRun: "",
    };
  return {
    installed,
    enabled: await command(
      "systemctl",
      ["--user", "is-enabled", "rprr.timer"],
      true,
    ),
    active: await command(
      "systemctl",
      ["--user", "is-active", "rprr.timer"],
      true,
    ),
    lastResult: await command(
      "systemctl",
      ["--user", "show", "rprr.service", "--property=Result", "--value"],
      true,
    ),
    nextRun: await command(
      "systemctl",
      [
        "--user",
        "show",
        "rprr.timer",
        "--property=NextElapseUSecRealtime",
        "--value",
      ],
      true,
    ),
  };
}
